command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "main fetch failed"}
$temp=Join-Path $env:RUNNER_TEMP ("remote-profile-write-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp 72cfa6b962aca2ea351af354091f1f3230deeb91
  if($LASTEXITCODE -ne 0){throw "main worktree failed"}
  Set-Location -LiteralPath $temp
  & python -X utf8 tools\winui\run_checks.py infra
  if($LASTEXITCODE -ne 0){throw "infra validation failed"}
  Write-Host "REMOTE_WRITE_PROFILE_ALIGNMENT=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
